import React, { useState, useEffect } from "react";
import { collection, addDoc, onSnapshot, query, orderBy } from "firebase/firestore";
import { db } from "./firebaseConfig";

export default function Chat({ user }) {
  const [msg, setMsg] = useState("");
  const [mensagens, setMensagens] = useState([]);

  useEffect(() => {
    const q = query(collection(db, "mensagens"), orderBy("timestamp"));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      setMensagens(snapshot.docs.map(doc => doc.data()));
    });
    return () => unsubscribe();
  }, []);

  const enviarMensagem = async () => {
    if (msg.trim() === "") return;
    await addDoc(collection(db, "mensagens"), {
      texto: msg,
      usuario: user.email,
      timestamp: new Date()
    });
    setMsg("");
  };

  return (
    <div style={{width:"400px", margin:"auto", textAlign:"center"}}>
      <h2>Chat em tempo real</h2>
      <div style={{border:"1px solid #ccc", height:"300px", overflowY:"auto"}}>
        {mensagens.map((m, i) => (
          <p key={i}><b>{m.usuario}:</b> {m.texto}</p>
        ))}
      </div>
      <input value={msg} onChange={e => setMsg(e.target.value)} placeholder="Digite sua mensagem" />
      <button onClick={enviarMensagem}>Enviar</button>
    </div>
  );
}
